def delete_node(cm, current):
    tree = cm.tree
    parent = tree[current]['parent']
    if tree[current]['right'] == EMPTY:
        replacement = tree[current]['left']
        if replacement == EMPTY:
            # no children
            if parent == EMPTY:
                assert cm.ttop == current
                cm.ttop = EMPTY
            elif tree[parent]['left'] == current:
                tree[parent]['left'] = EMPTY
            else:
                assert tree[parent]['right'] == current
                tree[parent]['right'] = EMPTY
        else:
            # one child (left)
            tree[replacement]['parent'] = parent
            if parent == EMPTY:
                tree[replacement]['parent'] = EMPTY
                cm.ttop = replacement
            elif tree[parent]['left'] == current:
                tree[parent]['left'] = replacement
            else:
                assert tree[parent]['right'] == current
                tree[parent]['right'] = replacement
    elif tree[current]['left'] == EMPTY:
        replacement = tree[current]['right']
        # one child (right)
        tree[replacement]['parent'] = parent
        if parent == EMPTY:
            tree[replacement]['parent'] = EMPTY
            cm.ttop = replacement
        elif tree[parent]['left'] == current:
            tree[parent]['left'] = replacement
        else:
            assert tree[parent]['right'] == current
            tree[parent]['right'] = replacement
    else:
        # two children: find successor (leftmost of right subtree)
        amputee = tree[current]['right']
        replacement = amputee
        while tree[replacement]['left'] != EMPTY:
            amputee = replacement
            replacement = tree[replacement]['left']
        # amputee is parent of replacement; unlink replacement
        if amputee == current:
