    return replacement

adds = 0

def add_range(cm, low, high, out, check_for_overlap, many, depth=0):
    global adds
    adds += 1
    tree = cm.tree  # cached pointer (list object identity stays same in sim; we track resize)
    current = EMPTY

    if cm.tlen:
        move = cm.ttop
        gt = EMPTY
        lt = EMPTY
        if check_for_overlap:
            while True:
                current = move
                if low <= tree[current]['low'] and tree[current]['low'] <= high:
                    tree[current]['out'] += high + 1 - tree[current]['low']
                    tree[current]['low'] = high + 1
                    if tree[current]['low'] > tree[current]['high']:
                        move = delete_node(cm, current)
                        current = EMPTY
                        if move == EMPTY:
                            break
                        continue
                elif low <= tree[current]['high'] and tree[current]['high'] <= high:
                    tree[current]['high'] = low - 1
                    assert tree[current]['low'] <= tree[current]['high']
                elif tree[current]['low'] < low and high < tree[current]['high']:
                    # case 3
                    new_high = tree[current]['high']
                    tree[current]['high'] = low - 1
                    print(f"{'  '*depth}case3 split at pre-tlen={cm.tlen} tcap={cm.tcap} depth={depth}; recursing add({high+1},{new_high})")
                    add_range(cm, high + 1, new_high, tree[current]['out'] + high + 1 - tree[current]['low'], 0, many, depth+1)
                    # after recursion, C uses STALE tree pointer if recursion resized
                    if cm.resized_at is not None and cm.resized_at[-1][1] == depth+1 and cm.resized_at[-1][2]:
                        print(f"{'  '*depth}*** STALE POINTER USE after resize in recursion at pre-tlen log -> CRASH (tree[current].low read) ***")
                        cm.crashed = True
                # where to move next
                if current == EMPTY:
                    # after delete, move was set
                    pass
                if tree[current]['low'] > high:
                    move = tree[current]['left']
                    gt = current
                else:
                    move = tree[current]['right']
                    lt = current
                if move == EMPTY:
                    break
        else:
            while True:
                current = move
                if tree[current]['low'] > high:
                    move = tree[current]['left']
                    gt = current
                else:
                    move = tree[current]['right']
                    lt = current
                if move == EMPTY:
