                tree[lt]['high'] = high
                if gt != EMPTY and not tree[gt]['many'] and tree[gt]['low'] == high + 1 and tree[gt]['out'] - tree[gt]['low'] == out - low:
                    tree[lt]['high'] = tree[gt]['high']
                    delete_node(cm, gt)
                print(f"{'  '*depth}MERGE-lt add({low},{high}) -> tlen={cm.tlen}")
                return
            if gt != EMPTY and not tree[gt]['many'] and tree[gt]['low'] == high + 1 and tree[gt]['out'] - tree[gt]['low'] == out - low:
                tree[gt]['low'] = low
                tree[gt]['out'] = out
                print(f"{'  '*depth}MERGE-gt add({low},{high}) -> tlen={cm.tlen}")
                return
    if cm.tlen == cm.tcap:
        new_cap = cm.tcap * 2 if cm.tcap else 256
        # mark resize event: (pre tlen, depth, did_resize)
        cm.resized_at = cm.resized_at or []
        cm.resized_at.append((cm.tlen, depth, True))
        print(f"{'  '*depth}RESIZE at pre-tlen={cm.tlen} cap {cm.tcap}->{new_cap} depth={depth}")
